import sys

def process_string(s):
    n = len(s)
    result = []
    for i in range(n):
        suffix = s[i:]
        stack = []
        for char in suffix:
            if stack and stack[-1] == char:
                stack.pop()
            else:
                stack.append(char)
        res = ''.join(stack)
        if len(res) > 10:
            res = res[:5] + '...' + res[-2:]
        result.append(str(len(res)) + ' ' + res if res else str(len(res)))
    return result

s = sys.stdin.read().strip()
output = process_string(s)
for line in output:
    print(line)
